update public.questions set subject = 'Polity', topic = 'Fundamental Rights, DPSP & Duties', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about how far Articles 19 and 21 reach:', body_hi = 'अनुच्छेद 19 और 21 की पहुँच के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 3 are correct. In Paschim Banga Khet Mazdoor Samity an injured man was turned away by several government hospitals for want of beds; the Court held that preserving human life is the State''s primary duty under Article 21, that a government hospital failing to give timely treatment violates that right, and that a lack of funds is no excuse. In Ramlila Maidan, a midnight police action against a sleeping crowd was held to violate the right to sleep, part of the right to life and personal liberty. Statement 2 reverses the holding: Subramanian Swamy upheld criminal defamation (now in the Bharatiya Nyaya Sanhita), reasoning that reputation is itself part of Article 21 and that defamation is a ground of restriction named in Article 19(2).', explanation_hi = 'कथन 1 और 3 सही हैं। पश्चिम बंगा खेत मज़दूर समिति मामले में एक घायल व्यक्ति को कई सरकारी अस्पतालों ने बिस्तर न होने के कारण लौटा दिया था; न्यायालय ने कहा कि मानव जीवन की रक्षा अनुच्छेद 21 के तहत राज्य का प्राथमिक कर्तव्य है, समय पर उपचार न देने वाला सरकारी अस्पताल इस अधिकार का उल्लंघन करता है, और धन की कमी कोई बहाना नहीं है। रामलीला मैदान मामले में सोती भीड़ पर आधी रात की पुलिस कार्रवाई को नींद के अधिकार का उल्लंघन माना गया, जो प्राण और दैहिक स्वतंत्रता के अधिकार का भाग है। कथन 2 निर्णय को उलट देता है: सुब्रमण्यम स्वामी मामले में आपराधिक मानहानि (अब भारतीय न्याय संहिता में) को वैध ठहराया गया, इस तर्क पर कि प्रतिष्ठा स्वयं अनुच्छेद 21 का भाग है और मानहानि अनुच्छेद 19(2) में दिया गया प्रतिबंध का एक आधार है।', concept_group_id = 'rights-internet-defamation-sleep', source_citation = 'Supreme Court of India -- Paschim Banga Khet Mazdoor Samity v. State of West Bengal (1996); Subramanian Swamy v. Union of India (2016); In re Ramlila Maidan Incident (2012).', question_data = '{"statements": ["In Paschim Banga Khet Mazdoor Samity (1996), the Supreme Court held that a government hospital''s failure to give timely emergency treatment to an injured person violates Article 21.", "In Subramanian Swamy v. Union of India (2016), the Supreme Court struck down criminal defamation as an unreasonable restriction on free speech.", "In the Ramlila Maidan case (2012), the Supreme Court treated the right to sleep as part of the right to life under Article 21."], "statements_hi": ["पश्चिम बंगा खेत मज़दूर समिति (1996) में सर्वोच्च न्यायालय ने कहा कि किसी घायल व्यक्ति को समय पर आपातकालीन उपचार न देकर सरकारी अस्पताल अनुच्छेद 21 का उल्लंघन करता है।", "सुब्रमण्यम स्वामी बनाम भारत संघ (2016) में सर्वोच्च न्यायालय ने आपराधिक मानहानि को अभिव्यक्ति की स्वतंत्रता पर अनुचित प्रतिबंध मानकर रद्द कर दिया।", "रामलीला मैदान मामले (2012) में सर्वोच्च न्यायालय ने नींद के अधिकार को अनुच्छेद 21 के तहत जीवन के अधिकार का भाग माना।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft') and concept_group_id = 'rights-internet-defamation-sleep' returning concept_group_id;
commit;
